{
  "title": "add-machine-fingerprint-to-telemetry",
  "request": "Can we include the machine fingerprint in every telemetry event? I'd like a "machine_fingerprint" field in the captured properties when it's available.",
  "edits": [
    {
      "path": "browser_use/telemetry/service.py",
      "search": "self._posthog_client.capture(
					distinct_id=self.user_id,
					event=event.name,
					properties={**event.properties, **POSTHOG_EVENT_SETTINGS},
				)",
      "replace": "props = {**event.properties, **POSTHOG_EVENT_SETTINGS}
					# Add a machine fingerprint if we can generate one
					fingerprint = _machine_fingerprint()
					if fingerprint:
						props["machine_fingerprint"] = fingerprint
					self._posthog_client.capture(
						distinct_id=self.user_id,
						event=event.name,
						properties=props,
					)"
    }
  ],
  "test_path": "tests/telemetry/test_machine_fingerprint_property.py",
  "test": "import pytest

from browser_use.telemetry.service import ProductTelemetry

class DummyClient:
    def __init__(self):
        self.captured = []

    def capture(self, distinct_id, event, properties):
        self.captured.append({"distinct_id": distinct_id, "event": event, "properties": properties})

    def flush(self):
        pass

class DummyEvent:
    name = "test_event"
    properties = {"foo": "bar"}

def test_machine_fingerprint_added(monkeypatch):
    # Obtain a fresh telemetry instance (singleton may cache, but we replace its client)
    telemetry = ProductTelemetry()
    dummy = DummyClient()
    # Replace the real Posthog client with our dummy to capture calls
    telemetry._posthog_client = dummy
    # Force a known user id to avoid environment dependencies
    telemetry._curr_user_id = "test_user"
    # Directly invoke the internal capture method
    telemetry._direct_capture(DummyEvent())
    # Ensure that at least one captured event includes the fingerprint field
    assert dummy.captured, "No events were captured"
    captured_props = dummy.captured[0]["properties"]
    assert "machine_fingerprint" in captured_props, "machine_fingerprint not added to properties"
"
